import {themes as prismThemes} from 'prism-react-renderer';
import type {Config, Plugin} from '@docusaurus/types';
import type * as Preset from '@docusaurus/preset-classic';
import type {VersionOptions} from '@docusaurus/plugin-content-docs';
import fs from 'node:fs';
import path from 'node:path';

// This runs in Node.js - Don't use client-side code here (browser APIs, JSX...)

const libraryDir = '../gs1-parser';

/**
 * Labels of the API versions generated by scripts/generate-api-versions.mjs,
 * showing the full release version (e.g. "2.2.1") instead of the minor version
 */
function getApiVersionLabels(): Record<string, VersionOptions> {
  if (!fs.existsSync('api_versions.json')) return {};
  const versions: string[] = JSON.parse(fs.readFileSync('api_versions.json', 'utf8'));
  return Object.fromEntries(
    versions.map((version) => {
      const tag = fs.readFileSync(`api_versioned_docs/version-${version}/.tag`, 'utf8');
      return [version, {label: tag.replace(/^v/, '')}];
    }),
  );
}

/** Resolves the library to its sources, so the site always uses the current code */
function librarySourcePlugin(): Plugin {
  return {
    name: 'library-source',
    configureWebpack() {
      return {
        resolve: {
          alias: {
            '@valentynb/gs1-parser$': path.resolve(libraryDir, 'src/index.ts'),
          },
        },
      };
    },
  };
}

